// Copies api/*.ts into functions/api/*.ts so Cloudflare Pages picks them up.
//
// Each generated file is just a thin re-export of the source module's
// `onRequest`. We don't fork the code — we depend on the source file
// retaining its dual-platform exports (see api/README.md).
//
// Run: `node scripts/build-cf-functions.mjs` (called by `npm run build:cf`).

import { mkdir, readdir, rm, writeFile } from 'node:fs/promises';
import { dirname, join, relative, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const root = resolve(here, '..');
const SRC = join(root, 'api');
const DST = join(root, 'functions', 'api');

async function main() {
  await rm(DST, { recursive: true, force: true });
  await mkdir(DST, { recursive: true });

  const entries = await readdir(SRC, { withFileTypes: true });
  let count = 0;

  for (const entry of entries) {
    if (!entry.isFile()) continue;
    if (!entry.name.endsWith('.ts')) continue;
    if (entry.name.startsWith('_')) continue; // helpers — don't route
    if (entry.name.toLowerCase() === 'readme.md') continue;

    const stem = entry.name.replace(/\.ts$/, '');
    const fromCf = join(DST, `${stem}.ts`);
    const importPath = relative(dirname(fromCf), join(SRC, stem)).replace(/\\/g, '/');

    const body = `// Auto-generated by scripts/build-cf-functions.mjs — DO NOT EDIT.
// Source: api/${stem}.ts (see api/README.md for the dual-platform pattern).
export { onRequest } from '${importPath.startsWith('.') ? importPath : `./${importPath}`}';
`;
    await writeFile(fromCf, body, 'utf8');
    count += 1;
  }

  console.log(`build-cf-functions: emitted ${count} function${count === 1 ? '' : 's'} to ${relative(root, DST)}`);
}

main().catch((err) => {
  console.error('build-cf-functions failed:', err);
  process.exit(1);
});
